import { resolveWorkspaceRuntimeRootSync } from '../../../domains/workflow-contract/workspace-runtime.js';
import { promises as fs } from 'node:fs';
import { execFileSync } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';
import { parse, stringify } from 'yaml';
import { afterEach, describe, expect, it } from 'vitest';
import {
  createFileRuntimeStore,
  createRuntime,
  portableClaimToken,
  readPortableRunCheckpoint,
  type WorkflowRun,
} from '../../../domains/engine/runtime.js';
import { runClassicCli } from '../../../domains/comet-classic/classic-cli.js';
import { withClassicCommandContext } from '../../../domains/comet-classic/classic-command-context.js';
import {
  classicOpenEvidenceReceipt,
  defineClassicAgentWorkflowApplication,
  defineClassicWorkflowApplication,
} from '../../../domains/comet-classic/classic-sdk-application.js';
import { createClassicSdkStateStore } from '../../../domains/comet-classic/classic-sdk-state-store.js';
import {
  parseClassicStateDocument,
  CLASSIC_MANAGED_RUN_MARKER,
} from '../../../domains/comet-classic/classic-state.js';
import {
  COMET_CHANGE_OWNER_SCHEMA,
  registerSdkChangeOwner,
} from '../../../domains/workflow-contract/change-runtime-owner.js';
import { prepareClassicLegacyProject } from '../../helpers/classic-project.js';
import type { ApplicationIdentity } from '../../../domains/workflow-application/index.js';

const roots: string[] = [];
afterEach(async () => {
  await Promise.all(roots.splice(0).map((root) => fs.rm(root, { recursive: true, force: true })));
});
async function fixture(custom = false) {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-sdk-recovery-'));
  roots.push(root);
  await prepareClassicLegacyProject(root);
  execFileSync('git', ['init', '-b', 'main'], { cwd: root, stdio: 'ignore' });
  const name = 'demo';
  const changeDir = path.join(root, 'openspec/changes/demo');
  const stateFile = path.join(changeDir, 'comet-state.yaml');
  const markerFile = path.join(
    resolveWorkspaceRuntimeRootSync(root),
    'state-projections/classic/demo.json',
  );
  const cli = (...args: string[]) =>
    withClassicCommandContext({ projectRoot: root, invocationCwd: root }, () =>
      runClassicCli(['state', ...args, '--json']),
    );
  const identity: ApplicationIdentity | undefined = custom
    ? {
        id: 'custom-classic',
        version: '1',
        base: 'classic-hotfix',
        contentHash: 'a'.repeat(64),
        packageRoot: path.join(root, 'package'),
        projectRoot: root,
        runtimeVersion: '0.4.5',
      }
    : undefined;
  const application = custom
    ? defineClassicWorkflowApplication('hotfix')
    : defineClassicAgentWorkflowApplication('hotfix');
  const store = createClassicSdkStateStore(root, { identity });
  const runtime = createRuntime({
    ...application,
    store,
    workflows: [application.workflow],
    transitionHandlers: [application.transitionHandler],
  });
  if (custom) {
    await fs.mkdir(changeDir, { recursive: true });
    const state = parseClassicStateDocument({
      workflow: 'hotfix',
      language: 'en',
      phase: 'open',
      design_doc: null,
      plan: null,
      build_mode: null,
      isolation: 'current',
      bound_branch: 'main',
      verify_mode: null,
      verify_result: 'pending',
      verified_at: null,
      archived: false,
    }).classic!;
    await runtime.start({
      runId: name,
      workflow: { id: application.workflow.id, version: application.workflow.version },
      input: { change: name, changeDir: 'openspec/changes/demo' },
      initialState: state as never,
    });
    await store.read(name);
    await registerSdkChangeOwner(root, {
      schema: COMET_CHANGE_OWNER_SCHEMA,
      workflow: 'classic',
      change: name,
      format: 'sdk',
      application: identity!.id,
      runId: name,
    });
    const document = parse(await fs.readFile(stateFile, 'utf8'));
    document.language = 'zh-CN';
    await fs.writeFile(stateFile, CLASSIC_MANAGED_RUN_MARKER + stringify(document));
  } else {
    expect((await cli('init', name, 'hotfix', '--isolation', 'current')).exitCode).toBe(0);
    expect((await cli('set', name, 'language', 'zh-CN')).exitCode).toBe(0);
  }
  const run = await store.read(name);
  const raw = createFileRuntimeStore<WorkflowRun>({
    rootDir: path.join(resolveWorkspaceRuntimeRootSync(root), 'sdk-runs/classic'),
  });
  const checkpoint = async () =>
    readPortableRunCheckpoint(parse(await fs.readFile(stateFile, 'utf8')).run_checkpoint, name, {
      preserveSourceRevision: true,
    })!;
  const loseRun = () =>
    fs.rm(path.join(resolveWorkspaceRuntimeRootSync(root), 'sdk-runs/classic'), {
      recursive: true,
    });
  return {
    root,
    name,
    cli,
    runtime,
    store,
    raw,
    run: run!,
    identity,
    stateFile,
    changeDir,
    markerFile,
    checkpoint,
    loseRun,
  };
}

describe('Classic trusted checkpoint recovery', () => {
  it.each(['run', 'projection', 'runtime'])(
    'recovers missing %s at the original revision without replaying Open',
    async (missing) => {
      const f = await fixture();
      const saved = await f.checkpoint();
      expect(saved!.revision).toBeGreaterThan(1);
      if (missing === 'run') await f.loseRun();
      else
        await fs.rm(
          path.join(
            resolveWorkspaceRuntimeRootSync(f.root),
            missing === 'projection' ? 'state-projections' : '',
          ),
          { recursive: true },
        );
      const restored = await createClassicSdkStateStore(f.root).read(f.name);
      expect(restored).toEqual(saved);
      expect(await createClassicSdkStateStore(f.root).read(f.name)).toEqual(restored);
      expect(JSON.parse(await fs.readFile(f.markerFile, 'utf8')).revision).toBe(saved!.revision);
      expect(await f.raw.compareAndSwap(f.name, 1, { ...saved!, revision: 2 })).toBe(false);
      expect((await f.cli('next', f.name)).exitCode).toBe(0);
    },
  );

  it.each(['missing-store', 'replaced-git'])(
    'restores Build with its completed Open, evidence and pending Action intact (%s)',
    async (loss) => {
      const f = await fixture();
      for (const file of ['proposal.md', 'design.md', 'tasks.md'])
        await fs.writeFile(
          path.join(f.changeDir, file),
          file === 'tasks.md' ? '- [ ] Implement the change\n' : `# ${file}\n`,
        );
      const action = f.run.actions[0];
      await f.runtime.claim({
        runId: f.name,
        actionId: action.id,
        attempt: action.attempt,
        inputHash: action.inputHash,
        executorId: 'classic-host',
        claimToken: 'open-claim',
      });
      let run = await f.runtime.recordOutcome({
        runId: f.name,
        outcome: {
          actionId: action.id,
          attempt: action.attempt,
          inputHash: action.inputHash,
          claimToken: 'open-claim',
          outcomeId: 'open-result',
          status: 'succeeded',
          output: { event: 'open-complete' },
        },
      });
      run = await f.runtime.recordEvidence({
        runId: f.name,
        evidenceId: run.evidenceWaits![0].id,
        kind: 'classic-open-artifacts',
        ...(await classicOpenEvidenceReceipt(f.root, 'openspec/changes/demo')),
        contentHash: action.inputHash,
        submissionId: 'open-evidence',
        expectedRevision: run.revision,
        context: { requestId: 'open-evidence', projectRoot: f.root },
      });
      expect(run.state).toMatchObject({ phase: 'build' });
      const saved = await f.checkpoint();
      const original = await f.raw.read(f.name);
      if (loss === 'missing-store') await f.loseRun();
      else {
        const backup = `${f.root}-git-backup`;
        roots.push(backup);
        await fs.rename(path.join(f.root, '.git'), backup);
        execFileSync('git', ['init', '-b', 'main'], { cwd: f.root, stdio: 'ignore' });
        await expect(f.store.read(f.name)).rejects.toThrow('workspace identity changed');
        await expect(f.store.readProjection!(f.name)).rejects.toThrow('workspace identity changed');
        await expect(
          f.store.compareAndSwap(f.name, original!.revision, {
            ...original!,
            revision: original!.revision + 1,
          }),
        ).rejects.toThrow('workspace identity changed');
        expect(await f.raw.read(f.name)).toEqual(original);
      }
      const recovered = await createClassicSdkStateStore(f.root).read(f.name);
      expect(recovered).toEqual(saved);
      expect(recovered!.actions.map((item) => item.id)).toEqual(run.actions.map((item) => item.id));
      expect((await f.cli('next', f.name)).exitCode).toBe(0);
    },
  );

  it('keeps an in-flight claim unknown after replacing Git identity and never rewrites the old store', async () => {
    const f = await fixture();
    const action = f.run.actions[0];
    const claimed = await f.runtime.claim({
      runId: f.name,
      actionId: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      executorId: 'classic-host',
      claimToken: 'interrupted-before-git-replacement',
    });
    const original = await f.raw.read(f.name);
    const backup = `${f.root}-git-backup`;
    roots.push(backup);
    await fs.rename(path.join(f.root, '.git'), backup);
    execFileSync('git', ['init', '-b', 'main'], { cwd: f.root, stdio: 'ignore' });
    await expect(f.store.read(f.name)).rejects.toThrow('workspace identity changed');
    await expect(f.store.readProjection!(f.name)).rejects.toThrow('workspace identity changed');
    const recovered = await createClassicSdkStateStore(f.root).read(f.name);
    expect(recovered!.revision).toBe(claimed.revision);
    expect(recovered!.actions[0]).toMatchObject({
      id: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      claim: {
        ...claimed.actions[0].claim,
        token: portableClaimToken(claimed.actions[0].claim!.token),
      },
      status: 'unknown',
    });
    expect(recovered!.actions).toHaveLength(claimed.actions.length);
    expect(await f.raw.read(f.name)).toEqual(original);
  });

  it.each(['read', 'readProjection'] as const)(
    'rejects Git identity replacement during %s without rewriting the original store',
    async (operation) => {
      const f = await fixture();
      const original = await f.raw.read(f.name);
      const originalMarker = await fs.readFile(f.markerFile, 'utf8');
      const originalDocument = await fs.readFile(f.stateFile, 'utf8');
      const backup = `${f.root}-git-backup`;
      roots.push(backup);
      let replaced = false;
      const readThenReplaceIdentity = async (runId: string) => {
        const run = await f.raw.read(runId);
        if (!replaced) {
          replaced = true;
          await fs.rename(path.join(f.root, '.git'), backup);
          execFileSync('git', ['init', '-b', 'main'], { cwd: f.root, stdio: 'ignore' });
        }
        return run;
      };
      const store = createClassicSdkStateStore(f.root, {
        store: {
          ...f.raw,
          read: readThenReplaceIdentity,
          readProjection: readThenReplaceIdentity,
        },
      });
      await expect(store[operation]!(f.name)).rejects.toThrow('workspace identity changed');
      expect(replaced).toBe(true);
      expect(await f.raw.read(f.name)).toEqual(original);
      expect(await fs.readFile(f.markerFile, 'utf8')).toBe(originalMarker);
      expect(await fs.readFile(f.stateFile, 'utf8')).toBe(originalDocument);
    },
  );

  it.each([false, true])(
    'preserves user configuration during a legacy recovery with partial import=%s',
    async (partial) => {
      const f = await fixture();
      const document = parse(await fs.readFile(f.stateFile, 'utf8'));
      delete document.run_checkpoint.sourceRevision;
      delete document.run_checkpoint.sourceHash;
      document.review_mode = 'thorough';
      await fs.writeFile(f.stateFile, CLASSIC_MANAGED_RUN_MARKER + stringify(document));
      await f.loseRun();
      if (partial)
        await f.raw.compareAndSwap(f.name, null, {
          ...document.run_checkpoint.run,
          state: parseClassicStateDocument(document).classic,
        });
      const restored = await createClassicSdkStateStore(f.root).read(f.name);
      expect(restored!.revision).toBe(f.run.revision + 1);
      expect(restored!.state).toMatchObject({ reviewMode: 'thorough' });
      expect(restored!.actions).toEqual(document.run_checkpoint.run.actions);
      expect(await f.raw.compareAndSwap(f.name, 1, { ...restored!, revision: 2 })).toBe(false);
      expect(await createClassicSdkStateStore(f.root).read(f.name)).toEqual(restored);
    },
  );

  it('retries after publishing the Run and before completing projection', async () => {
    const f = await fixture();
    const saved = await f.checkpoint();
    await f.loseRun();
    await fs.rm(f.markerFile);
    const interrupted = createClassicSdkStateStore(f.root, {
      store: {
        ...f.raw,
        async restoreCheckpoint(...args) {
          await f.raw.restoreCheckpoint!(...args);
          throw new Error('simulated projection interruption');
        },
      },
    });
    await expect(interrupted.read(f.name)).rejects.toThrow(/projection interruption/);
    expect(await f.raw.read(f.name)).toEqual(saved);
    expect(await createClassicSdkStateStore(f.root).read(f.name)).toEqual(saved);
    expect(JSON.parse(await fs.readFile(f.markerFile, 'utf8')).revision).toBe(saved!.revision);
  });

  it.each([
    'checkpoint',
    'source-revision',
    'marker',
    'future-marker',
    'state',
    'branch',
    'partial',
  ])('rejects %s drift without replacing history or user files', async (damage) => {
    const f = await fixture();
    if (damage === 'branch')
      execFileSync('git', ['symbolic-ref', 'HEAD', 'refs/heads/other'], { cwd: f.root });
    else if (damage.includes('marker')) {
      const marker = JSON.parse(await fs.readFile(f.markerFile, 'utf8'));
      if (damage === 'future-marker') marker.revision += 1;
      else marker.state.language = 'en';
      await fs.writeFile(f.markerFile, JSON.stringify(marker));
    } else if (damage !== 'partial') {
      const document = parse(await fs.readFile(f.stateFile, 'utf8'));
      if (damage === 'checkpoint') document.run_checkpoint.hash = '0'.repeat(64);
      else if (damage === 'source-revision') document.run_checkpoint.sourceRevision += 20;
      else document.phase = 'build';
      await fs.writeFile(f.stateFile, CLASSIC_MANAGED_RUN_MARKER + stringify(document));
    }
    await f.loseRun();
    if (damage === 'partial')
      await f.raw.compareAndSwap(f.name, null, {
        ...(await f.checkpoint())!,
        revision: 1,
        state: { ...(f.run.state as object), phase: 'build' },
      });
    const before = await fs.readFile(f.stateFile, 'utf8');
    const original = await f.raw.read(f.name);
    await expect(createClassicSdkStateStore(f.root).read(f.name)).rejects.toThrow();
    expect(await f.raw.read(f.name)).toEqual(original);
    expect(await fs.readFile(f.stateFile, 'utf8')).toBe(before);
  });

  it('requires the original fixed application and preserves its custom checkpoint identity', async () => {
    const f = await fixture(true);
    const saved = await f.checkpoint();
    await f.loseRun();
    await expect(createClassicSdkStateStore(f.root).read(f.name)).rejects.toThrow(
      /original fixed Application/,
    );
    await expect(
      createClassicSdkStateStore(f.root, {
        identity: { ...f.identity!, contentHash: 'b'.repeat(64) },
      }).read(f.name),
    ).rejects.toThrow(/original fixed Application/);
    await expect(
      createClassicSdkStateStore(f.root, {
        identity: f.identity,
        store: { read: f.raw.read, compareAndSwap: f.raw.compareAndSwap },
      }).read(f.name),
    ).rejects.toThrow(/restoreCheckpoint support/);
    expect(await f.raw.read(f.name)).toBeNull();
    expect(await createClassicSdkStateStore(f.root, { identity: f.identity }).read(f.name)).toEqual(
      saved,
    );
  });
});

import { execFileSync } from 'node:child_process';
import { ensureClassicRuntimeRun } from '../../../domains/comet-classic/classic-runtime-run.js';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { runClassicCli } from '../../../domains/comet-classic/classic-cli.js';
import { withClassicCommandContext } from '../../../domains/comet-classic/classic-command-context.js';
import { readClassicState } from '../../../domains/comet-classic/classic-store.js';
import {
  readTrajectory,
  appendTrajectory,
} from '../../../domains/comet-classic/classic-run-store.js';
import { resolveClassicRunDirectory } from '../../../domains/comet-classic/classic-runtime-paths.js';
import { createClassicSdkStateStore } from '../../../domains/comet-classic/classic-sdk-state-store.js';
import {
  classicProjectTargetExists,
  readClassicProjectFile,
  writeClassicProjectText,
} from '../../../domains/comet-classic/classic-protected-path.js';
import {
  isWorkspaceRuntimeMigrationFence,
  resolveWorkspaceRuntimeRoot,
} from '../../../domains/workflow-contract/workspace-runtime.js';
import { prepareClassicLegacyProject } from '../../helpers/classic-project.js';

describe('Classic workspace-local runtime storage', () => {
  let directory: string;
  let root: string;
  let change: string;
  beforeEach(async () => {
    directory = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-classic-home-'));
    vi.stubEnv('COMET_DATA_DIR', path.join(directory, 'user-data'));
    root = path.join(directory, 'project');
    await fs.mkdir(root);
    await prepareClassicLegacyProject(root);
    change = path.join(root, 'openspec', 'changes', 'demo');
  });
  afterEach(async () => {
    vi.unstubAllEnvs();
    await fs.rm(directory, { recursive: true, force: true });
  });
  async function initialize(runtime: 'compat' | 'sdk') {
    const result = await withClassicCommandContext({ projectRoot: root, invocationCwd: root }, () =>
      runClassicCli(['state', 'init', 'demo', 'full', '--runtime', runtime, '--json']),
    );
    expect(result.exitCode, result.stderr).toBe(0);
  }

  it('blocks old compat writers immediately after initialization and permits current writes', async () => {
    await initialize('compat');
    const lock = path.join(change, '.comet-state.lock');
    const runtime = await resolveWorkspaceRuntimeRoot(root);
    expect(
      await isWorkspaceRuntimeMigrationFence(lock, path.join(runtime, 'classic-legacy-state.lock')),
    ).toBe(true);
    await expect(fs.open(lock, 'wx')).rejects.toMatchObject({ code: 'EEXIST' });
    await expect(fs.access(path.join(change, '.comet', 'run-state.json'))).rejects.toMatchObject({
      code: 'ENOENT',
    });
    const result = await withClassicCommandContext({ projectRoot: root, invocationCwd: root }, () =>
      runClassicCli(['state', 'set', 'demo', 'language', 'zh-CN', '--json']),
    );
    expect(result.exitCode, result.stderr).toBe(0);
    expect(await fs.readFile(path.join(change, '.comet.yaml'), 'utf8')).toContain(
      'language: zh-CN',
    );
    expect(await fs.lstat(lock).then((stat) => stat.isDirectory())).toBe(true);
  });

  it('blocks old compat writers when adopting YAML with no legacy local records', async () => {
    await fs.mkdir(change, { recursive: true });
    await fs.writeFile(path.join(change, '.comet.yaml'), 'workflow: full\nphase: open\n');
    const local = await resolveClassicRunDirectory(change, root);
    await expect(fs.open(path.join(change, '.comet-state.lock'), 'wx')).rejects.toMatchObject({
      code: 'EEXIST',
    });
    expect(await resolveClassicRunDirectory(change, root)).toBe(local);
    await expect(fs.access(path.join(local, '.comet-state.lock'))).rejects.toMatchObject({
      code: 'ENOENT',
    });
  });

  it('keeps compat Run state, trajectory and Skill snapshots outside the project', async () => {
    await initialize('compat');
    await ensureClassicRuntimeRun(change);
    const projection = await readClassicState(change);
    expect(projection.run).not.toBeNull();
    const local = await resolveClassicRunDirectory(change, root);
    expect(local.startsWith(path.join(directory, 'user-data') + path.sep)).toBe(true);
    expect(await fs.readFile(path.join(local, '.comet', 'run-state.json'), 'utf8')).toContain(
      projection.run!.runId,
    );
    expect(await fs.readdir(path.join(local, '.comet', 'skill-snapshots'))).toContain(
      projection.run!.skillHash,
    );
    await expect(fs.access(path.join(change, '.comet', 'run-state.json'))).rejects.toMatchObject({
      code: 'ENOENT',
    });
    await appendTrajectory(change, projection.run!.trajectoryRef, {
      sequence: 100,
      timestamp: new Date().toISOString(),
      type: 'home-test',
      runId: projection.run!.runId,
      data: {},
    });
    expect((await readTrajectory(change, projection.run!.trajectoryRef)).at(-1)?.type).toBe(
      'home-test',
    );
    expect(await fs.readFile(path.join(change, '.comet.yaml'), 'utf8')).toContain('run_id:');
  });

  it('stores SDK Run and projection at the workspace root and retains portable YAML', async () => {
    await initialize('sdk');
    const run = await createClassicSdkStateStore(root).read('demo');
    expect(run?.runId).toBe('demo');
    const runtime = await resolveWorkspaceRuntimeRoot(root);
    expect(await fs.readdir(path.join(runtime, 'sdk-runs', 'classic'))).not.toHaveLength(0);
    expect(
      await fs.readFile(path.join(runtime, 'state-projections', 'classic', 'demo.json'), 'utf8'),
    ).toContain('demo');
    await expect(fs.access(path.join(root, '.comet', 'runtime', 'sdk-runs'))).rejects.toMatchObject(
      { code: expect.stringMatching(/ENOENT|ENOTDIR/) },
    );
    expect(await fs.readFile(path.join(change, 'comet-state.yaml'), 'utf8')).toContain(
      'run_checkpoint:',
    );
  });

  it('migrates legacy local logs while preserving handoff and resolves them after archive', async () => {
    await fs.mkdir(path.join(change, '.comet', 'checks'), { recursive: true });
    await fs.mkdir(path.join(change, '.comet', 'handoff'));
    await fs.writeFile(path.join(change, '.comet.yaml'), 'workflow: full\nphase: open\n');
    await fs.writeFile(path.join(change, '.comet', 'checks', 'old.log'), 'old execution evidence');
    await fs.writeFile(path.join(change, '.comet', 'handoff', 'context.json'), '{"portable":true}');
    const ref = 'openspec/changes/demo/.comet/checks/old.log';
    expect(await readClassicProjectFile(root, ref, { label: 'legacy check' })).toBe(
      'old execution evidence',
    );
    await writeClassicProjectText(root, ref, 'new execution evidence', { label: 'local check' });
    const local = await resolveClassicRunDirectory(change, root);
    expect(await fs.readFile(path.join(local, '.comet', 'checks', 'old.log'), 'utf8')).toBe(
      'new execution evidence',
    );
    expect(
      await fs.readFile(path.join(change, '.comet', 'handoff', 'context.json'), 'utf8'),
    ).toContain('portable');
    const archived = path.join(root, 'openspec', 'changes', 'archive', '2026-10-11-demo');
    await fs.mkdir(path.dirname(archived), { recursive: true });
    await fs.rename(change, archived);
    expect(await resolveClassicRunDirectory(archived, root)).toBe(local);
    expect(
      await readClassicProjectFile(root, path.join(archived, '.comet', 'checks', 'old.log'), {
        label: 'archived check',
      }),
    ).toBe('new execution evidence');
  });

  it('keeps the same instance after checkout recreation and separates reused names', async () => {
    await initialize('compat');
    await ensureClassicRuntimeRun(change);
    const first = await readClassicState(change);
    const original = await resolveClassicRunDirectory(change, root);
    const yaml = await fs.readFile(path.join(change, '.comet.yaml'));
    await fs.rm(change, { recursive: true });
    await fs.mkdir(change);
    await fs.writeFile(path.join(change, '.comet.yaml'), yaml);
